import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(
        csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False,
        )
    )

    if not records:
        return {"columns": [], "rows": []}

    expected_width = 9
    header_index = next(
        (i for i, record in enumerate(records) if len(record) == expected_width),
        0,
    )

    columns = list(records[header_index])
    data = records[:header_index] + records[header_index + 1:]
    width = max(
        expected_width,
        len(columns),
        max((len(record) for record in data), default=0),
    )

    columns.extend(
        f"column_{i + 1}" for i in range(len(columns), width)
    )
    rows = [
        list(record) + [""] * (width - len(record))
        for record in data
    ]

    return {"columns": columns, "rows": rows}
